import type { SceneDrawing } from '../scene-drawing.ts';
import { trackPixelSource } from '../../platform/pixel-memory.ts';
import { createAssetMaterials } from '../asset-materials.ts';
import {
  createCachedMaterials,
  clearCachedMaterial,
  drawCachedImage,
  cachedMaterialContext,
} from '../cached-materials.ts';
import { invalidateSceneTexture, retireSceneTexture } from '../texture-revision.ts';
import { drawAtlasSprite, releaseSceneryCutouts } from './scene-kit.ts';
import { registerMaterialSink } from '../scene-material.ts';
import {
  materialTextureUploads,
  nextVisibleFrame,
  type TextureUpload,
  type WarmSceneTextures,
} from '../texture-upload.ts';
import type { EnvironmentFrame } from './local-renderer.ts';
import { compositionKey } from './worker-types.ts';
import { markScenePhase } from '../../platform/scene-timing.ts';

const landmarkUrl = new URL('./assets/demon-landmarks-atlas.webp', import.meta.url).href;
const terrainUrl = new URL('./assets/demon-terrain-atlas.webp', import.meta.url).href;
const mountainUrl = new URL('./assets/mountain-atlas.webp', import.meta.url).href;

/** Independently placed atlas props over a procedural sky; no flattened backdrop. */
export function createDemonRealmRenderer(
  doc: Document,
  options: {
    warmScene?: WarmSceneTextures;
    retainSources?: (sources: Iterable<TextureUpload['texture']['source']>) => () => void;
  } = {},
) {
  const materials = createAssetMaterials<string>(doc, {
    landmarks: landmarkUrl,
    terrain: terrainUrl,
    mountains: mountainUrl,
  });
  const cachedMaterials = createCachedMaterials();
  const landmarks = trackPixelSource(doc, doc.createElement('img'), 'decoded'),
    terrain = trackPixelSource(doc, doc.createElement('img'), 'decoded'),
    mountains = trackPixelSource(doc, doc.createElement('img'), 'decoded');
  landmarks.decoding = terrain.decoding = mountains.decoding = 'async';
  const mountainLayer = trackPixelSource(doc, doc.createElement('canvas'), 'canvas');
  let mountainKey = '';
  let disposed = false;
  let pending: Promise<boolean> | undefined;
  let generation = 0,
    capturing = false,
    preparedKey = '',
    requestKey = '';
  let warming: AbortController | undefined, preparedSources: (() => void) | undefined;
  const lifetime = new AbortController();
  function loadArtwork(): Promise<boolean> {
    if (disposed) return Promise.resolve(false);
    const current = generation;
    return (pending ??= (async () => {
      landmarks.src = landmarkUrl;
      terrain.src = terrainUrl;
      mountains.src = mountainUrl;
      try {
        await Promise.all([
          landmarks.decode(),
          terrain.decode(),
          mountains.decode(),
          materials.prepare(),
        ]);
        if (
          disposed ||
          current !== generation ||
          !materials.ready('landmarks') ||
          !materials.ready('terrain') ||
          !materials.ready('mountains')
        )
          return false;
        cachedMaterials.bind(landmarks, (frame) => materials.material('landmarks', frame));
        cachedMaterials.bind(terrain, (frame) => materials.material('terrain', frame));
        cachedMaterials.bind(mountains, (frame) => materials.material('mountains', frame));
        mountainKey = '';
        return true;
      } catch {
        return false;
      }
    })().then((ready) => {
      if (!ready && current === generation) {
        pending = undefined;
        if (!disposed) {
          materials.select({});
          materials.select({ landmarks: landmarkUrl, terrain: terrainUrl, mountains: mountainUrl });
          for (const image of [landmarks, terrain, mountains]) image.removeAttribute('src');
        }
      }
      return ready;
    }));
  }
  function prepare(frame?: EnvironmentFrame, signal?: AbortSignal): Promise<boolean> {
    if (!frame || !options.warmScene) return loadArtwork();
    warming?.abort();
    warming = new AbortController();
    const controller = warming;
    const abort = AbortSignal.any([
      controller.signal,
      lifetime.signal,
      ...(signal ? [signal] : []),
    ]);
    const current = generation;
    const key = compositionKey(frame);
    const seed = frame.stageSeed ?? 131304;
    requestKey = key;
    return (async () => {
      if (!(await loadArtwork()) || abort.aborted || current !== generation) return false;
      markScenePhase('assets-ready', `true:${key}`, { backend: 'demon' });
      if (!(await nextVisibleFrame(doc, abort))) return false;
      const canvas = trackPixelSource(doc, doc.createElement('canvas'), 'canvas');
      canvas.width = canvas.height = 1;
      const context = canvas.getContext('2d')!;
      const uploads: TextureUpload[] = [];
      const captureStart = performance.now();
      registerMaterialSink(context, {
        draw: ({ texture, material }) => uploads.push(...materialTextureUploads(texture, material)),
        lights() {},
      });
      try {
        capturing = true;
        owner.draw(context, frame.width, frame.height, 0, frame.reducedMotion, seed);
      } finally {
        capturing = false;
        canvas.width = canvas.height = 0;
      }
      markScenePhase('demon-artwork-built', `true:${key}`, {
        duration: performance.now() - captureStart,
      });
      if (abort.aborted || current !== generation || requestKey !== key) return false;
      const release = options.retainSources?.(uploads.map(({ texture }) => texture.source));
      let accepted = false;
      try {
        if (
          !(await options.warmScene!(uploads, abort)) ||
          abort.aborted ||
          current !== generation ||
          requestKey !== key
        )
          return false;
        preparedSources?.();
        preparedSources = release;
        preparedKey = `${frame.width}:${frame.height}:${seed}`;
        markScenePhase('textures-warmed', `true:${key}`, { backend: 'demon', prewarmed: true });
        accepted = true;
        return true;
      } finally {
        if (!accepted) release?.();
      }
    })();
  }
  function release() {
    if (!pending && !warming && !mountainKey && !preparedKey) return;
    generation++;
    warming?.abort();
    warming = undefined;
    preparedSources?.();
    preparedSources = undefined;
    preparedKey = requestKey = mountainKey = '';
    pending = undefined;
    cachedMaterials.releaseSources();
    clearCachedMaterial(mountainLayer, false);
    retireSceneTexture(mountainLayer);
    releaseSceneryCutouts([landmarks, terrain, mountains]);
    materials.select({});
    for (const image of [landmarks, terrain, mountains]) {
      retireSceneTexture(image);
      image.removeAttribute('src');
    }
    mountainLayer.width = mountainLayer.height = 0;
    if (!disposed)
      materials.select({ landmarks: landmarkUrl, terrain: terrainUrl, mountains: mountainUrl });
  }
  function stamp(
    g: SceneDrawing,
    image: HTMLImageElement,
    cell: number,
    x: number,
    base: number,
    width: number,
    alpha = 1,
    distant = false,
  ) {
    if (!image.complete || !image.naturalWidth) return;
    const terrainFrames = [
      [21, 231, 580, 285],
      [650, 240, 586, 285],
      [17, 716, 594, 353],
      [645, 782, 593, 298],
    ] as const;
    const landmarkBases = [550, 552, 528, 533];
    const frame =
      image === terrain
        ? terrainFrames[cell]!
        : [
            ((cell % 2) * image.naturalWidth) / 2,
            (Math.floor(cell / 2) * image.naturalHeight) / 2,
            image.naturalWidth / 2,
            image.naturalHeight / 2,
          ];
    const [sx, sy, sw, sh] = frame;
    const anchor = image === terrain ? (cell === 2 ? 0.94 : 0.93) : landmarkBases[cell]! / 627;
    g.save();
    g.translate(x, base);
    if (distant) g.transform(1, 0, 0.018, 0.98, 0, 0);
    drawAtlasSprite(g, image, cell, 0, 0, width, {
      frame: { x: sx!, y: sy!, width: sw, height: sh },
      anchorY: anchor,
      alpha: image === terrain ? 0.94 : alpha === 1 ? 0.88 : alpha,
      hazeColor: distant ? '#46354d' : '#382b3c',
    });
    g.restore();
  }
  const owner = {
    prepare,
    release,
    snapshot: () => ({ texturesWarmed: preparedKey !== '' }),
    draw(
      g: SceneDrawing,
      width: number,
      height: number,
      time = 0,
      reducedMotion = false,
      seed = 131304,
    ): boolean {
      if (disposed) return false;
      const variation = (i: number) => {
        const n = Math.sin(seed * 0.731 + i * 12.9898) * 43758.5453;
        return n - Math.floor(n);
      };
      const sky = g.createLinearGradient(0, 0, 0, height);
      sky.addColorStop(0, '#110d1a');
      sky.addColorStop(0.48, '#35213c');
      sky.addColorStop(1, '#0e0c10');
      g.fillStyle = sky;
      g.fillRect(0, 0, width, height);
      const moonX = width * (0.42 + variation(0) * 0.35),
        moonY = height * 0.19,
        radius = Math.min(width, height) * 0.075;
      const halo = g.createRadialGradient(moonX, moonY, radius * 0.3, moonX, moonY, radius * 3);
      halo.addColorStop(0, 'rgba(189,155,180,.19)');
      halo.addColorStop(1, 'rgba(100,70,110,0)');
      g.fillStyle = halo;
      g.fillRect(0, 0, width, height * 0.6);
      g.fillStyle = '#958592';
      g.beginPath();
      g.arc(moonX, moonY, radius, 0, Math.PI * 2);
      g.fill();
      const artworkReady =
        !options.warmScene || capturing || preparedKey === `${width}:${height}:${seed}`;
      if (artworkReady) {
        if (mountains.complete && mountains.naturalWidth) {
          const key = `${width}:${height}:${seed}`;
          if (mountainKey !== key) {
            clearCachedMaterial(mountainLayer);
            mountainLayer.width = Math.ceil(width);
            mountainLayer.height = Math.ceil(height);
            const nativeContext = mountainLayer.getContext('2d');
            if (nativeContext) {
              const far = cachedMaterialContext(nativeContext);
              const span = Math.max(width * 0.62, height * 0.8);
              const count = Math.ceil(width / (span * 0.7)) + 2;
              for (let i = 0; i < count; i++)
                drawAtlasSprite(
                  far,
                  mountains,
                  (i + Math.floor(variation(6) * 4)) % 4,
                  (i - 0.5) * span * 0.7,
                  height * (0.59 + variation(i + 20) * 0.025),
                  span,
                  { flip: i % 2 === 0, fadeFrom: 0.65, alpha: 0.45, hazeColor: '#584052' },
                );
              mountainKey = key;
              invalidateSceneTexture(mountainLayer);
            }
          }
          g.save();
          drawCachedImage(
            g,
            mountainLayer,
            [0, 0, mountainLayer.width, mountainLayer.height],
            0,
            0,
            width,
            height,
          );
          g.restore();
        }
        stamp(
          g,
          landmarks,
          0,
          width * (0.32 + variation(1) * 0.26),
          height * 0.65,
          Math.min(Math.max(width * 1.15, height * 0.67), height * 0.78),
          0.3,
          true,
        );
        stamp(
          g,
          landmarks,
          2,
          width * (0.76 + variation(2) * 0.18),
          height * 0.65,
          Math.min(Math.max(width * 0.5, height * 0.37), height * 0.62),
          0.8,
        );
        stamp(
          g,
          landmarks,
          1,
          width * (0.04 + variation(3) * 0.18),
          height * 0.75,
          Math.min(Math.max(width * 0.36, height * 0.33), height * 0.55),
        );
        stamp(
          g,
          terrain,
          0,
          width * (0.38 + variation(4) * 0.24),
          height * 1.06,
          Math.min(width * 0.9, height * 0.65),
        );
        const bankWidth = Math.min(width * 0.6, height * 0.75);
        stamp(g, terrain, 1, width * 0.04, height * 0.98, bankWidth);
        stamp(g, terrain, 1, width * 0.96, height * 0.98, bankWidth);
        stamp(
          g,
          terrain,
          2,
          width * 0.03,
          height * 0.87,
          Math.min(Math.max(width * 0.33, 130), height * 0.45),
        );
        stamp(
          g,
          terrain,
          3,
          width * 0.92,
          height * 1.02,
          Math.min(Math.max(width * 0.35, 150), height * 0.45),
        );
        stamp(
          g,
          landmarks,
          3,
          width * 1.02,
          height * 0.93,
          Math.min(Math.max(width * 0.4, height * 0.38), height * 0.6),
        );
      }
      const t = reducedMotion ? 0 : time;
      for (let i = 0; i < 5; i++) {
        const y = height * (0.43 + i * 0.074);
        const shift = Math.sin(t * 0.12 + i) * width * 0.05;
        const mist = g.createRadialGradient(
          width * 0.5 + shift,
          y,
          0,
          width * 0.5 + shift,
          y,
          width * 0.6,
        );
        mist.addColorStop(0, 'rgba(146,96,153,.045)');
        mist.addColorStop(1, 'rgba(146,96,153,0)');
        g.fillStyle = mist;
        // Keep the mist's clipping edges on logical pixels. Fractional strip
        // edges can resolve differently on the first native MSAA composite.
        const top = Math.round(y - height * 0.06),
          bottom = Math.round(y + height * 0.06);
        g.fillRect(0, top, width, bottom - top);
      }
      for (let i = 0; i < 18; i++) {
        const rise = (t * 0.04 + i / 18) % 1;
        g.fillStyle = `rgba(210,78,66,${(1 - rise) * 0.28})`;
        g.fillRect((((i * 137) % 997) / 997) * width, height * (0.94 - rise * 0.65), 1.5, 2);
      }
      return (
        landmarks.complete &&
        landmarks.naturalWidth > 0 &&
        terrain.complete &&
        terrain.naturalWidth > 0 &&
        mountains.complete &&
        mountains.naturalWidth > 0
      );
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      lifetime.abort();
      release();
      materials.dispose();
      cachedMaterials.dispose();
    },
  };
  return owner;
}
